import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [showQR, setShowQR] = useState(false);
  const [screenshot, setScreenshot] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");

  const [userId, setUserId] = useState("");
  const [approved, setApproved] = useState(false);
  const [photo, setPhoto] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* LOAD FACE MODEL */
  useEffect(() => {
    const loadModels = async () => {
      await faceapi.nets.tinyFaceDetector.loadFromUri("/models");
    };
    loadModels();
  }, []);

  /* AUTO CHECK APPROVAL */
  useEffect(() => {
    const interval = setInterval(async () => {
      if (!userId) return;

      try {
        const res = await axios.get(
          `http://localhost:5000/verify-user/${userId}`
        );

        if (res.data.success) {
          if (res.data.user.payment_status === "approved") {
            setApproved(true);
            setStatusMsg("✅ Payment Approved!");
          }
        }
      } catch (err) {
        console.log(err);
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [userId]);

  /* INPUT */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* SHOW PAYMENT */
  const handlePayment = (e) => {
    e.preventDefault();
    setShowQR(true);
  };

  /* SUBMIT */
  const confirmPayment = async () => {
    if (!screenshot) return alert("Upload screenshot!");

    const form = new FormData();
    Object.keys(formData).forEach((key) => {
      form.append(key, formData[key]);
    });
    form.append("screenshot", screenshot);

    try {
      const res = await axios.post(
        "http://localhost:5000/register",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      if (res.data.success) {
        setUserId(res.data.userId);
        setStatusMsg("⏳ Waiting for admin approval");
      }
    } catch {
      alert("Upload failed");
    }
  };

  /* CAMERA */
  const openCamera = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    videoRef.current.play();
  };

  const capturePhoto = async () => {
    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length !== 1) {
      return alert("Only one face allowed");
    }

    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    canvas.getContext("2d").drawImage(videoRef.current, 0, 0);
    setPhoto(canvas.toDataURL());

    streamRef.current.getTracks().forEach((t) => t.stop());
  };

  /* DOWNLOAD */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  const upiString = `upi://pay?pa=arunsekar664@okaxis&pn=Event&am=100&cu=INR`;

  const box = {
    padding: "20px",
    borderRadius: "10px",
    background: "#222",
    width: "300px",
    margin: "auto",
  };

  const input = {
    padding: "10px",
    margin: "5px",
    width: "100%",
  };

  const btn = {
    padding: "10px",
    background: "orange",
    border: "none",
    cursor: "pointer",
  };

  return (
    <div style={{ textAlign: "center", color: "white" }}>
      <Navbar />
      <h2>🚀 Event Registration</h2>

      {!showQR && (
        <form onSubmit={handlePayment} style={box}>
          <input name="name" placeholder="Name" style={input} onChange={handleChange} required />
          <input name="college_name" placeholder="College" style={input} onChange={handleChange} required />
          <input name="phone" placeholder="Phone" style={input} onChange={handleChange} required />
          <input name="email" placeholder="Email" style={input} onChange={handleChange} required />

          <h3>{eventName}</h3>
          <button style={btn}>Proceed to Pay</button>
        </form>
      )}

      {showQR && !approved && (
        <div style={box}>
          <h3>Scan & Pay</h3>
          <QRCode value={upiString} size={200} />

          <input type="file" onChange={(e) => setScreenshot(e.target.files[0])} />

          <button style={btn} onClick={confirmPayment}>Submit</button>
          <p>{statusMsg}</p>
        </div>
      )}

      {approved && !photo && (
        <div style={box}>
          <h3>Payment Approved</h3>
          <QRCode value={userId} size={150} />

          <button style={btn} onClick={openCamera}>Open Camera</button>
          <video ref={videoRef} style={{ width: "100%" }} />

          <button style={btn} onClick={capturePhoto}>Capture</button>
          <canvas ref={canvasRef} style={{ display: "none" }} />
        </div>
      )}

      {photo && (
        <div>
          <div ref={idCardRef} style={{ background: "white", color: "black", padding: "20px", width: "250px", margin: "auto" }}>
            <h3>EVENT PASS</h3>
            <p>{formData.name}</p>
            <p>ID: {userId}</p>
            <p>{eventName}</p>
            <QRCode value={userId} size={100} />
            <img src={photo} alt="" style={{ width: "100px" }} />
          </div>

          <button style={btn} onClick={downloadCard}>Download ID</button>
        </div>
      )}
    </div>
  );
}

export default Register;
